API endpoints for screenshot-based event extraction
"""

import logging
from datetime import datetime, time, timedelta
from uuid import UUID

from django.db import transaction
from django.shortcuts import get_object_or_404
from django.utils import timezone
from rest_framework import status
from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.request import Request
from rest_framework.response import Response

from users.models import FamilyMembership

from .models import Event, EventDraft, EventParticipant
from .serializers import EventDraftSerializer

logger = logging.getLogger(__name__)


def _clean(value: object) -> str | None:
    """Normalise form values: treat empty, "null", "None" as missing."""
    if value is None:
        return None
    text = str(value).strip()
    if text == "" or text.lower() in ("null", "none"):
        return None
    return text


@api_view(["POST"])
@permission_classes([IsAuthenticated])
def screenshot_upload(request: Request) -> Response:
    """
    Upload a screenshot to extract events from using AI

    Expected multipart/form-data with 'screenshot' file field
    Returns the created draft with processing status
    """
    if "screenshot" not in request.FILES:
        return Response(
            {"error": "No screenshot file provided"}, status=status.HTTP_400_BAD_REQUEST
        )

    try:
        # Create the EventDraft instance
        draft = EventDraft.objects.create(
            creator=request.user,  # type: ignore[misc]
            screenshot=request.FILES["screenshot"],
            processing_status="PENDING",
        )

        # Trigger AI processing
        from events.media_services import ScreenshotProcessorService

        processing_result = ScreenshotProcessorService.process_screenshot(draft)

        # Refresh from DB to get updated data
        draft.refresh_from_db()

        # Prepare response
        response_data = {
            "draft_id": str(draft.id),
            "processing_status": draft.processing_status,
            "message": "Screenshot processed successfully"
            if processing_result.get("success")
            else f"Screenshot uploaded but processing encountered an issue: {processing_result.get('error', 'Unknown error')}",
        }

        return Response(response_data, status=status.HTTP_201_CREATED)

    except Exception as e:
        logger.error(
            f"Error processing screenshot upload for user {request.user.id}: {str(e)}",
            exc_info=True,
        )
        return Response(
            {
                "error": "There was an error processing your screenshot. Please try again."
            },
            status=status.HTTP_500_INTERNAL_SERVER_ERROR,
        )


@api_view(["GET"])
@permission_classes([IsAuthenticated])
def screenshot_review(request: Request, draft_id: str) -> Response:
    """
    Get the draft with extracted events for review

    Returns the draft with AI-extracted event data
    """
    draft = get_object_or_404(EventDraft, id=draft_id, creator=request.user)

    serializer = EventDraftSerializer(draft, context={"request": request})
    return Response(serializer.data)


@api_view(["POST"])
@permission_classes([IsAuthenticated])
def screenshot_create_events(request: Request, draft_id: str) -> Response:
    """
    Create events from the extracted draft data

    Expected POST data format:
    {
        "selected_events": [0, 1, 2],  // Array of event indices to create
        "event_0_title": "Meeting",
        "event_0_description": "Team sync",
        "event_0_location": "Office",
        "event_0_start_date": "2025-10-10",
        "event_0_start_time": "14:00",
        "event_0_end_date": "2025-10-10",
        "event_0_end_time": "15:00",
        "event_0_family": "uuid",
        ... (repeat for each selected event)
    }

    Returns:
    {
        "success": true,
        "created_count": 2,
        "message": "Successfully created 2 events from the screenshot"
    }
    """
    draft = get_object_or_404(EventDraft, id=draft_id, creator=request.user)

    # Get selected events
    selected_events = request.data.get("selected_events", [])
    if not selected_events:
        return Response(
            {"error": "No events selected"}, status=status.HTTP_400_BAD_REQUEST
        )

    created_count = 0
    errors = []
    from typing import cast

    from django.contrib.auth.models import User

    from users.services.email_addresses import is_user_email_verified

    user = cast(User, request.user)
    user_is_verified = is_user_email_verified(user)

    try:
        with transaction.atomic():
            for event_index in selected_events:
                event_index = int(event_index)
                if event_index >= len(draft.extracted_data.get("events", [])):
                    errors.append(f"Event index {event_index} is out of range")
                    continue

                event_data = draft.extracted_data["events"][event_index]

                # Get form data for this event (fall back to AI-extracted values)
                title = (
                    _clean(request.data.get(f"event_{event_index}_title"))
                    or _clean(event_data.get("title"))
                    or ""
                )
                description = (
                    _clean(request.data.get(f"event_{event_index}_description"))
                    or _clean(event_data.get("description"))
                    or ""
                )
                location = (
                    _clean(request.data.get(f"event_{event_index}_location"))
                    or _clean(event_data.get("location"))
                    or ""
                )
                family_id = _clean(request.data.get(f"event_{event_index}_family"))

                # Parse dates and times — treat "", "null", "None" as missing so
                # the default "start + 1h" branch below can fire.
                start_date = _clean(
                    request.data.get(f"event_{event_index}_start_date")
                ) or _clean(event_data.get("start_date"))
                start_time = _clean(
                    request.data.get(f"event_{event_index}_start_time")
                ) or _clean(event_data.get("start_time"))
                end_date = (
                    _clean(request.data.get(f"event_{event_index}_end_date"))
                    or _clean(event_data.get("end_date"))
                    or start_date
                )
                end_time = _clean(
                    request.data.get(f"event_{event_index}_end_time")
                ) or _clean(event_data.get("end_time"))
                all_day = event_data.get("all_day", False)

                if not title or not start_date or not family_id:
                    errors.append(f"Event '{title}' is missing required fields")
                    continue

                try:
                    family_uuid = UUID(family_id)
                except ValueError:
                    errors.append(f"Invalid family id for event '{title}'")
                    continue

                # Validate family access
                if not request.user.family_memberships.filter(  # type: ignore[union-attr]
                    family_id=family_uuid
                ).exists():
                    errors.append(f"User does not have access to family {family_id}")
                    continue

                # Create datetime objects with proper error handling
                try:
                    assert start_date is not None  # validated above
                    assert end_date is not None  # defaults to start_date above
                    start_datetime = datetime.strptime(start_date, "%Y-%m-%d")
                    end_datetime = datetime.strptime(end_date, "%Y-%m-%d")
                except ValueError as e:
                    errors.append(f"Invalid date format for event '{title}': {str(e)}")
                    continue

                if not all_day and start_time:
                    try:
                        start_time_obj = datetime.strptime(start_time, "%H:%M").time()
                        start_datetime = datetime.combine(
                            start_datetime.date(), start_time_obj
                        )
                    except ValueError as e:
                        errors.append(
                            f"Invalid start time format for event '{title}': {str(e)}"
                        )
                        continue

                    if end_time:
                        try:
                            end_time_obj = datetime.strptime(end_time, "%H:%M").time()
                            end_datetime = datetime.combine(
                                end_datetime.date(), end_time_obj
                            )
                        except ValueError as e:
                            errors.append(
                                f"Invalid end time format for event '{title}': {str(e)}"
                            )
                            continue

                        # Validate that end time is after start time
                        if end_datetime <= start_datetime:
                            errors.append(
                                f"End time must be after start time for event '{title}'"
                            )
                            continue
                    else:
                        # Default to 1 hour duration
                        end_datetime = start_datetime + timedelta(hours=1)
                else:
                    # For all-day events, set times to midnight
                    start_datetime = datetime.combine(start_datetime.date(), time.min)
                    end_datetime = datetime.combine(end_datetime.date(), time.max)

                # Validate that event dates are not in the distant past
                if start_datetime.date() < (
                    timezone.now().date() - timedelta(days=365)
                ):
                    errors.append(
                        f"Event date for '{title}' is more than a year in the past"
                    )
                    continue

                # Make timezone aware
                start_datetime = timezone.make_aware(start_datetime)
                end_datetime = timezone.make_aware(end_datetime)

                # Determine event type from AI extraction or form override
                event_type = request.data.get(
                    f"event_{event_index}_event_type",
                    event_data.get("event_type", "REGULAR"),
                )
                if event_type not in ("REGULAR", "PARTY", "MEETING", "APPOINTMENT"):
                    event_type = "REGULAR"

                if event_type == "PARTY" and not user_is_verified:
                    errors.append("Please verify your email to create Party events.")
                    continue

                # Visibility override from review UI (PUBLIC | PRIVATE | PERSONAL)
                visibility = (
                    _clean(request.data.get(f"event_{event_index}_visibility"))
                    or "PUBLIC"
                )
                if visibility not in ("PUBLIC", "PRIVATE", "PERSONAL"):
                    visibility = "PUBLIC"

                # Create the event
                event_obj = Event.objects.create(
                    title=title,
                    description=description,
                    location=location,
                    start_time=start_datetime,
                    end_time=end_datetime,
                    creator=request.user,  # type: ignore[misc]
                    family_group_id=family_id,
                    visibility=visibility,
                    event_type=event_type,
                )

                # Assign to one or more family members as participants (RSVP YES)
                raw_assigned = _clean(
                    request.data.get(f"event_{event_index}_assigned_user_ids")
                )
                if raw_assigned:
                    assigned_ids = [
                        uid.strip() for uid in raw_assigned.split(",") if uid.strip()
                    ]
                    # Only accept users who share a membership in the target family
                    valid_ids = set(
                        FamilyMembership.objects.filter(
                            family_id=family_id, user_id__in=assigned_ids
                        ).values_list("user_id", flat=True)
                    )
                    if valid_ids:
                        EventParticipant.objects.bulk_create(
                            [
                                EventParticipant(
                                    event=event_obj,
                                    user_id=uid,
                                    rsvp_status="YES",
                                )
                                for uid in valid_ids
                            ],
                            ignore_conflicts=True,
                        )

                created_count += 1

            # Mark draft as completed
            if created_count > 0:
                draft.processing_status = "COMPLETED"
                draft.save(update_fields=["processing_status"])

    except Exception as e:
        logger.error(
            f"Error creating events from draft {draft_id}: {str(e)}", exc_info=True
        )
        return Response(
            {"error": "Failed to create events. Please try again."},
            status=status.HTTP_500_INTERNAL_SERVER_ERROR,
        )

    # Build response
    response_data = {
        "success": created_count > 0,
        "created_count": created_count,
        "message": f"Successfully created {created_count} event{'s' if created_count != 1 else ''} from the screenshot",
    }

    if errors:
        response_data["errors"] = errors

    return Response(response_data, status=status.HTTP_200_OK)
